fn add_residue_whole_system_records_hardware_process_org_policy_zig() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    add_attractor(&dir);
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "burst traffic exceeds single host",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "scale service horizontally",
        ],
    );
    let add = run(
        &dir,
        &[
            "add",
            "residue",
            "--force-id",
            "S-01",
            "--whole-system",
            "--notes",
            "hardware zig: add physical buffer appliance before cloud patch",
        ],
    );
    assert!(
        add.status.success(),
        "add residue --whole-system failed: {}",
        String::from_utf8_lossy(&add.stderr)
