//! +/- Residues schema — force ↔ component mapping.
//!
//! A residue does **not** hold the force narrative; that lives on Force.
//! Whole-system residues record surviving changes outside the software boundary
//! (hardware, process, organization, or policy).

/// Status when the surviving change leaves the software boundary.
pub const WHOLE_SYSTEM_STATUS: &str = "whole-system-residue";

/// Component id for residues whose change is not scoped to a software component.
pub const WHOLE_SYSTEM_COMPONENT: &str = "whole-system";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Residue {
    pub id: String,
    pub force_id: String,
    pub component_id: String,
    pub status: String,
    pub notes: String,
}

impl Residue {
    pub fn new(
        id: impl Into<String>,
        force_id: impl Into<String>,
        component_id: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            force_id: force_id.into(),
            component_id: component_id.into(),
            status: String::new(),
            notes: String::new(),
        }
    }

    /// Record a whole-system residue for a force when the zig survives outside software.
    pub fn whole_system(
        id: impl Into<String>,
        force_id: impl Into<String>,
        notes: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            force_id: force_id.into(),
            component_id: WHOLE_SYSTEM_COMPONENT.into(),
            status: WHOLE_SYSTEM_STATUS.into(),
            notes: notes.into(),
        }
    }

    pub fn is_whole_system(&self) -> bool {
        is_whole_system_residue(self)
    }
}

/// naive_change may encode a whole-system zig before a software-only patch.
pub fn naive_change_accepts_whole_system(naive_change: &str) -> bool {
    naive_change
        .to_lowercase()
        .contains(WHOLE_SYSTEM_STATUS)
}

pub fn is_whole_system_residue(residue: &Residue) -> bool {
    residue.status == WHOLE_SYSTEM_STATUS
        || residue.component_id == WHOLE_SYSTEM_COMPONENT
}

/// Prefix naive_change when the operator chose a whole-system zig first.
pub fn tag_naive_change_whole_system(naive_change: &str) -> String {
    if naive_change_accepts_whole_system(naive_change) {
        naive_change.to_string()
    } else {
        format!("{WHOLE_SYSTEM_STATUS}: {naive_change}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn whole_system_residue_marks_outside_software_boundary() {
        let r = Residue::whole_system("R-01", "S-01", "policy zig: retrain support");
        assert!(r.is_whole_system());
        assert_eq!(r.component_id, WHOLE_SYSTEM_COMPONENT);
        assert_eq!(r.status, WHOLE_SYSTEM_STATUS);
    }

    #[test]
    fn naive_change_accepts_whole_system_residue_token() {
        assert!(naive_change_accepts_whole_system("whole-system-residue: add buffer"));
        assert!(!naive_change_accepts_whole_system("add retry logic only"));
    }

    #[test]
    fn tag_naive_change_whole_system_prefixes_software_only_patch() {
        let tagged = tag_naive_change_whole_system("scale service horizontally");
        assert!(naive_change_accepts_whole_system(&tagged));
        assert!(tagged.contains("scale service"));
    }
}

use anyhow::{bail, Result};
use std::path::Path;

use crate::structure::analysis::residues::{is_whole_system_residue, Residue};
use crate::storage::format::{read_residues, write_residues};
use crate::storage::{purposes, stressors};

pub fn load(residual_dir: &Path) -> Result<Vec<Residue>> {
    read_residues(residual_dir)
}

pub fn next_id(existing: &[Residue]) -> String {
    let max = existing
        .iter()
        .filter_map(|r| r.id.strip_prefix('R'))
        .filter_map(|s| s.parse::<u32>().ok())
        .max()
        .unwrap_or(0);
    format!("R-{:02}", max + 1)
}

pub fn force_exists(residual_dir: &Path, force_id: &str) -> Result<bool> {
    if stressors::load(residual_dir)?
        .iter()
        .any(|s| s.id == force_id)
    {
        return Ok(true);
    }
    if purposes::load(residual_dir)?
        .iter()
        .any(|p| p.id == force_id)
    {
        return Ok(true);
    }
    Ok(crate::storage::format::read_forces(residual_dir)?
        .iter()
        .any(|f| f.id == force_id))
}

pub fn append(residual_dir: &Path, residue: Residue) -> Result<()> {
    let mut rows = load(residual_dir)?;
    if rows.iter().any(|r| r.id == residue.id) {
        bail!("residue id '{}' already exists", residue.id);
    }
    rows.push(residue);
    write_residues(residual_dir, &rows)
}

pub fn append_whole_system(
    residual_dir: &Path,
    force_id: &str,
    notes: &str,
) -> Result<String> {
    if notes.trim().is_empty() {
        bail!("--whole-system requires --notes describing the hardware, process, organization, or policy zig");
    }
    if !force_exists(residual_dir, force_id)? {
        bail!("force id '{}' not found in stressors, purposes, or forces", force_id);
    }
    let existing = load(residual_dir)?;
    let id = next_id(&existing);
    let residue = Residue::whole_system(id.clone(), force_id, notes);
    append(residual_dir, residue)?;
    Ok(id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;
    use crate::storage::stressors;

    #[test]
    fn append_whole_system_writes_residue_row() {
        let dir = tempdir().unwrap();
        stressors::append(
            dir.path(),
            stressors::Stressor {
                id: "S-01".into(),
                description: "d".into(),
                attractor_id: "A-01".into(),
                naive_change: "none".into(),
                outcomes: String::new(),
                components_affected: String::new(),
            },
        )
        .unwrap();
        let id = append_whole_system(dir.path(), "S-01", "hardware zig").unwrap();
        assert!(id.starts_with("R-"));
        let loaded = load(dir.path()).unwrap();
        assert_eq!(loaded.len(), 1);
        assert!(is_whole_system_residue(&loaded[0]));
    }

    #[test]
    fn append_whole_system_rejects_unknown_force() {
        let dir = tempdir().unwrap();
        let err = append_whole_system(dir.path(), "S-99", "notes").unwrap_err();
        assert!(err.to_string().contains("not found"));
    }
}

//! A-07 Software-Only Tunnel Vision — outcome contract tests.
//!
//! Force: S-23 (attractor_id A-07)
//! Outcome: operator examines whole-system-residue before recording a software-only naive change.

use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("failed to run residual binary")
}

fn init(dir: &TempDir) {
    let out = run(dir, &["init"]);
    assert!(out.status.success(), "init failed: {}", String::from_utf8_lossy(&out.stderr));
}

fn add_attractor(dir: &TempDir) {
    run(
        dir,
        &[
            "add",
            "attractor",
            "--name",
            "Ops",
            "--description",
            "on-call load",
            "--positive-state",
            "trained team",
            "--negative-state",
            "queue collapse",
        ],
    );
}

#[test]
fn add_stressor_whole_system_records_residue_and_tags_naive_change() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    add_attractor(&dir);
    let add = run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "support queue overwhelms on-call",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "add auto-retry in service",
            "--whole-system",
            "--notes",
            "policy zig: cap tickets and retrain support before software patch",
        ],
    );
    assert!(
        add.status.success(),
        "add stressor with --whole-system failed: {}",
        String::from_utf8_lossy(&add.stderr)
    );
    let residues = std::fs::read_to_string(dir.path().join("residual/residues.csv")).unwrap();
    assert!(
        residues.contains("whole-system-residue"),
        "expected whole-system-residue status in residues.csv, got:\n{residues}"
    );
    assert!(
        residues.contains("whole-system"),
        "expected whole-system component in residues.csv, got:\n{residues}"
    );
    let stressors = std::fs::read_to_string(dir.path().join("residual/stressors.csv")).unwrap();
    assert!(
        stressors.contains("whole-system-residue"),
        "naive_change should accept whole-system-residue token, got:\n{stressors}"
    );
}

#[test]
fn add_residue_whole_system_records_hardware_process_org_policy_zig() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    add_attractor(&dir);
    run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "burst traffic exceeds single host",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "scale service horizontally",
