    let add = run(
        &dir,
        &[
            "add",
            "residue",
            "--force-id",
            "S-01",
            "--whole-system",
            "--notes",
            "hardware zig: add physical buffer appliance before cloud patch",
        ],
    );
    assert!(
        add.status.success(),
        "add residue --whole-system failed: {}",
        String::from_utf8_lossy(&add.stderr)
    );
    let residues = std::fs::read_to_string(dir.path().join("residual/residues.csv")).unwrap();
    assert!(residues.contains("S-01"));
    assert!(residues.contains("whole-system-residue"));
    assert!(residues.contains("hardware zig"));
}

