//! +/- Residues schema — force ↔ component mapping.
//!
//! A residue does **not** hold the force narrative; that lives on Force.
//! Whole-system residues record surviving changes outside the software boundary
//! (hardware, process, organization, or policy).

/// Status when the surviving change leaves the software boundary.
pub const WHOLE_SYSTEM_STATUS: &str = "whole-system-residue";

/// Component id for residues whose change is not scoped to a software component.
pub const WHOLE_SYSTEM_COMPONENT: &str = "whole-system";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Residue {
    pub id: String,
    pub force_id: String,
    pub component_id: String,
    pub status: String,
    pub notes: String,
}

impl Residue {
    pub fn new(
        id: impl Into<String>,
        force_id: impl Into<String>,
        component_id: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            force_id: force_id.into(),
            component_id: component_id.into(),
            status: String::new(),
            notes: String::new(),
        }
    }

    /// Record a whole-system residue for a force when the zig survives outside software.
    pub fn whole_system(
        id: impl Into<String>,
        force_id: impl Into<String>,
        notes: impl Into<String>,
    ) -> Self {
        Self {
            id: id.into(),
            force_id: force_id.into(),
            component_id: WHOLE_SYSTEM_COMPONENT.into(),
            status: WHOLE_SYSTEM_STATUS.into(),
            notes: notes.into(),
        }
    }

    pub fn is_whole_system(&self) -> bool {
        is_whole_system_residue(self)
    }
}

/// naive_change may encode a whole-system zig before a software-only patch.
pub fn naive_change_accepts_whole_system(naive_change: &str) -> bool {
    naive_change
        .to_lowercase()
        .contains(WHOLE_SYSTEM_STATUS)
}

pub fn is_whole_system_residue(residue: &Residue) -> bool {
    residue.status == WHOLE_SYSTEM_STATUS
        || residue.component_id == WHOLE_SYSTEM_COMPONENT
}

/// Prefix naive_change when the operator chose a whole-system zig first.
pub fn tag_naive_change_whole_system(naive_change: &str) -> String {
    if naive_change_accepts_whole_system(naive_change) {
        naive_change.to_string()
    } else {
        format!("{WHOLE_SYSTEM_STATUS}: {naive_change}")
    }
}

