use anyhow::{bail, Result};
use std::path::Path;

use crate::structure::analysis::residues::{is_whole_system_residue, Residue};
use crate::storage::format::{read_residues, write_residues};
use crate::storage::{purposes, stressors};

pub fn load(residual_dir: &Path) -> Result<Vec<Residue>> {
    read_residues(residual_dir)
}

pub fn next_id(existing: &[Residue]) -> String {
    let max = existing
        .iter()
        .filter_map(|r| r.id.strip_prefix('R'))
        .filter_map(|s| s.parse::<u32>().ok())
        .max()
        .unwrap_or(0);
    format!("R-{:02}", max + 1)
}

pub fn force_exists(residual_dir: &Path, force_id: &str) -> Result<bool> {
    if stressors::load(residual_dir)?
        .iter()
        .any(|s| s.id == force_id)
    {
        return Ok(true);
    }
    if purposes::load(residual_dir)?
        .iter()
        .any(|p| p.id == force_id)
    {
        return Ok(true);
    }
    Ok(crate::storage::format::read_forces(residual_dir)?
        .iter()
        .any(|f| f.id == force_id))
}

pub fn append(residual_dir: &Path, residue: Residue) -> Result<()> {
    let mut rows = load(residual_dir)?;
    if rows.iter().any(|r| r.id == residue.id) {
        bail!("residue id '{}' already exists", residue.id);
    }
    rows.push(residue);
    write_residues(residual_dir, &rows)
}

pub fn append_whole_system(
    residual_dir: &Path,
    force_id: &str,
    notes: &str,
) -> Result<String> {
    if notes.trim().is_empty() {
        bail!("--whole-system requires --notes describing the hardware, process, organization, or policy zig");
    }
    if !force_exists(residual_dir, force_id)? {
        bail!("force id '{}' not found in stressors, purposes, or forces", force_id);
    }
    let existing = load(residual_dir)?;
    let id = next_id(&existing);
    let residue = Residue::whole_system(id.clone(), force_id, notes);
    append(residual_dir, residue)?;
    Ok(id)
}

//! A-07 Software-Only Tunnel Vision — outcome contract tests.
//!
//! Force: S-23 (attractor_id A-07)
//! Outcome: operator examines whole-system-residue before recording a software-only naive change.

use std::process::Command;
use tempfile::TempDir;

fn bin() -> std::path::PathBuf {
    env!("CARGO_BIN_EXE_residual").into()
}

fn run(dir: &TempDir, args: &[&str]) -> std::process::Output {
    Command::new(bin())
        .args(args)
        .current_dir(dir.path())
        .output()
        .expect("failed to run residual binary")
}

fn init(dir: &TempDir) {
    let out = run(dir, &["init"]);
    assert!(out.status.success(), "init failed: {}", String::from_utf8_lossy(&out.stderr));
}

fn add_attractor(dir: &TempDir) {
    run(
        dir,
        &[
            "add",
            "attractor",
            "--name",
            "Ops",
            "--description",
            "on-call load",
            "--positive-state",
            "trained team",
            "--negative-state",
            "queue collapse",
        ],
    );
}

#[test]
fn add_stressor_whole_system_records_residue_and_tags_naive_change() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    add_attractor(&dir);
    let add = run(
        &dir,
        &[
            "add",
            "stressor",
            "--description",
            "support queue overwhelms on-call",
            "--attractor-id",
            "A-01",
            "--naive-change",
            "add auto-retry in service",
            "--whole-system",
            "--notes",
            "policy zig: cap tickets and retrain support before software patch",
        ],
    );
    assert!(
        add.status.success(),
        "add stressor with --whole-system failed: {}",
        String::from_utf8_lossy(&add.stderr)
    );
    let residues = std::fs::read_to_string(dir.path().join("residual/residues.csv")).unwrap();
    assert!(residues.contains("whole-system-residue"));
    assert!(residues.contains("whole-system"));
    let stressors = std::fs::read_to_string(dir.path().join("residual/stressors.csv")).unwrap();
    assert!(stressors.contains("whole-system-residue"));
}

